	struct vm_area_struct *merge_res;
	VMG_MMAP_STATE(vmg, &map, vma);

	vma_iter_config(map.vmi, map.addr, map.end);
	merge_res = vma_merge_existing_range(&vmg);
	if (merge_res)
		vma = merge_res;
}

